import java.io.*;import java.nio.file.*;import java.sql.*;import java.time.*;import java.util.*;
public class PassMigration{
 static final String URL="jdbc:mariadb://localhost:3306/csa09_test",USER="root",PASS="change_me";record Rejected(int line,String reason){}
 public static void main(String[]a)throws Exception{if(a.length==0){System.err.println("Usage: java PassMigration migration-source.txt");return;}Path file=Path.of(a[0]);int read=0,ok=0;Set<String>ids=new HashSet<>();List<Rejected>bad=new ArrayList<>();
 try(Connection c=DriverManager.getConnection(URL,USER,PASS)){c.setAutoCommit(false);String sql="INSERT INTO bus_pass(pass_id,register_no,name,route_no,boarding_stop,valid_until,amount_paise) VALUES(?,?,?,?,?,?,?)";try(PreparedStatement p=c.prepareStatement(sql);BufferedReader r=Files.newBufferedReader(file)){String line;while((line=r.readLine())!=null){read++;if(line.isBlank()){bad.add(new Rejected(read,"blank line"));continue;}try{String[]f=line.split("\\|",-1);if(f.length!=7)throw new IllegalArgumentException("expected 7 fields, found "+f.length);if(!f[0].matches("P\\d{4,7}"))throw new IllegalArgumentException("bad pass ID");if(!f[1].matches("\\d{9}"))throw new IllegalArgumentException("register number is not 9 digits");if(!f[2].matches("[A-Za-z .]{2,80}"))throw new IllegalArgumentException("bad name");if(!f[3].matches("R\\d+"))throw new IllegalArgumentException("bad route");if(!ids.add(f[0]))throw new IllegalArgumentException("duplicate pass ID in file");LocalDate d=LocalDate.parse(f[5]);if(d.isBefore(LocalDate.of(2020,1,1)))throw new IllegalArgumentException("validity date before 2020");long amount=Long.parseLong(f[6]);if(amount<=0)throw new IllegalArgumentException("amount is not positive");if(amount>5000000L)throw new IllegalArgumentException("amount above Rs 50,000 ceiling");p.setString(1,f[0]);p.setString(2,f[1]);p.setString(3,f[2]);p.setString(4,f[3]);p.setString(5,f[4]);p.setDate(6,Date.valueOf(d));p.setLong(7,amount);p.addBatch();ok++;}catch(Exception ex){bad.add(new Rejected(read,ex.getMessage()));}}p.executeBatch();c.commit();}catch(Exception e){c.rollback();throw e;}
 DatabaseMetaData m=c.getMetaData();System.out.println("Database: "+m.getDatabaseProductName()+" "+m.getDatabaseProductVersion());System.out.println("JDBC: "+m.getDriverName()+" "+m.getDriverVersion());System.out.println("Transactions: "+m.supportsTransactions()+"; batch: "+m.supportsBatchUpdates());try(ResultSet t=m.getTables(c.getCatalog(),null,"%",new String[]{"TABLE"})){while(t.next())System.out.println("Table: "+t.getString("TABLE_NAME"));}}
 System.out.printf("Lines read=%d; migrated=%d; rejected=%d; accounted=%s%n",read,ok,bad.size(),ok+bad.size()==read);for(Rejected x:bad)System.out.println("Line "+x.line()+": "+x.reason());}
}
